/// Prefix of the model metadata fallback warning emitted by codex-core.
const MODEL_METADATA_PREFIX: &str = "Model metadata for `";
/// Suffix of the model metadata fallback warning emitted by codex-core.
const MODEL_METADATA_SUFFIX: &str =
    "` not found. Defaulting to fallback metadata; this can degrade performance and cause issues.";

/// Tracks which warnings have already been displayed so that repeated,
/// model-specific metadata warnings do not clutter the conversation history.
#[derive(Default)]
pub(super) struct WarningDisplayState {
    /// Model slugs for which a metadata fallback warning has already been shown.
    seen_model_metadata_slugs: HashSet<String>,
}

impl WarningDisplayState {
    /// Returns `true` if the warning should be added to history.
    ///
    /// For the model metadata fallback warning, returns `true` the first time a
    /// given slug is seen and `false` for every subsequent occurrence of the
    /// same slug. All other warnings always return `true`.
    pub(super) fn should_display(&mut self, message: &str) -> bool {
        match model_metadata_slug(message) {
            Some(slug) => self.seen_model_metadata_slugs.insert(slug.to_string()),
            None => true,
        }
    }
}

/// Extracts the model slug from a model metadata fallback warning, if `message`
/// matches that exact pattern.
fn model_metadata_slug(message: &str) -> Option<&str> {
    message
        .strip_prefix(MODEL_METADATA_PREFIX)
        .and_then(|rest| rest.strip_suffix(MODEL_METADATA_SUFFIX))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn dedupes_model_metadata_warning_per_slug() {
        let mut state = WarningDisplayState::default();
        let msg = |slug: &str| {
            format!("Model metadata for `{slug}` not found. Defaulting to fallback metadata; this can degrade performance and cause issues.")
        };

        assert!(state.should_display(&msg("unknown-model")));
        assert!(!state.should_display(&msg("unknown-model")));
        assert!(state.should_display(&msg("other-model")));
        assert!(!state.should_display(&msg("other-model")));
    }

    #[test]
    fn always_displays_generic_warnings() {
        let mut state = WarningDisplayState::default();
        assert!(state.should_display("some other warning"));
        assert!(state.should_display("some other warning"));
    }
}
